import journal from './migrations/meta/_journal.json';

/**
 * Local SQLite migrations, generated by drizzle-kit from `tables.js` (run
 * `npm run db:generate` after changing it). Each one upgrades the database by
 * one version, tracked with PRAGMA user_version, in the journal's order.
 */
const files = import.meta.glob('./migrations/*.sql', { query: '?raw', import: 'default', eager: true });

export const migrations = journal.entries.map(({ tag }) => {
    const sql = files[`./migrations/${tag}.sql`];
    if (sql === undefined) throw new Error(`Migration ${tag}.sql is missing`);
    return sql;
});
